-- Dev/test-only credentials for the seeded platform admin (Admin portal → POST /api/v1/auth/admin/login),
-- password: admin-dev-2026
-- Existing local databases: apply once with
--   docker compose exec -T db psql -U bkktennis -d bkktennis -v ON_ERROR_STOP=1 < db/init/005_seed_admin.sql
-- The hash is generated by pgcrypto (bcrypt, cost 10) so nothing secret-looking is committed.

UPDATE users
SET email = 'admin@bkktennis.test', password_hash = crypt('admin-dev-2026', gen_salt('bf', 10))
WHERE id = '00000000-0000-0000-0000-000000000001' AND role = 'platform_admin';
